package com.weaponsregistration.inventory.model;import com.weaponsregistration.core.model.*;import jakarta.persistence.*;import java.time.LocalDate;
@Entity@Table(name="erp_certification_record",uniqueConstraints=@UniqueConstraint(columnNames={"organization_id","certification_type","certificate_number"}))public class CertificationRecord extends CoreEntity{@ManyToOne(optional=false)@JoinColumn(name="organization_id",nullable=false)public Organization organization;@ManyToOne@JoinColumn(name="unit_id")public OrganizationalUnit unit;@ManyToOne@JoinColumn(name="asset_id")public AssetItem asset;@ManyToOne@JoinColumn(name="lot_id")public StockLot lot;@Column(name="certification_type",nullable=false)public String type;@Column(name="certificate_number",nullable=false)public String number;@Column(nullable=false)public LocalDate validUntil;@Column(nullable=false)public String status;}
